GET /api/trade/vocab/heading-qualifiers.body:
{
  "schema": "artbitrage.vocab/1",
  "id": "heading-qualifiers",
  "title": "Catalogue heading qualifiers — the authenticity ladder",
  "note": "Heading language is a graded authenticity code: only the unqualified heading is warranty-bearing at the major houses. Meanings quoted from each house's Explanation of Cataloguing Practice.",
  "source_status": {
    "sothebys": "verified",
    "christies": "source-declared"
  },
  "sources": {
    "sothebys": "https://help.sothebys.com/en/support/solutions/articles/44002518846-guide-for-buyers-glossary-important-notices",
    "christies": "https://images.liveauctioneers.com/houses/christie/ECOMMERCE_CONDITIONS_OF_SALE_HongKong_ENGLISH_8Feb2022.pdf"
  },
  "terms": [
    {
      "code": "full-attribution",
      "warranty_bearing": true,
      "display_pattern": "NAME(S) OR RECOGNISED DESIGNATION OF AN ARTIST WITHOUT ANY QUALIFICATION (UPPERCASE type, first line of catalogue description = the 'Heading')",
      "meanings": {
        "christies": "In Christie's opinion a work by the artist.",
        "sothebys": "The work is, in our best judgement, by the named artist."
      }
    },
    {
      "code": "attributed-to",
      "warranty_bearing": false,
      "display_pattern": "\"Attributed to …\"",
      "meanings": {
        "christies": "In Christie's qualified opinion probably a work by the artist in whole or in part.",
        "sothebys": "In our opinion, probably a work by the artist but less certainty as to authorship is expressed than in the preceding category."
      }
    },
    {
      "code": "studio-of",
      "warranty_bearing": false,
      "display_pattern": "\"Studio of …\" / \"Workshop of …\"",
      "meanings": {
        "christies": "In Christie's qualified opinion a work executed in the studio or workshop of the artist, possibly under his supervision.",
        "sothebys": "In our opinion, a work by an unknown hand in the studio of the artist which may or may not have been executed under the artist's direction."
      }
    },
    {
      "code": "circle-of",
      "warranty_bearing": false,
      "display_pattern": "\"Circle of …\"",
      "meanings": {
        "christies": "In Christie's qualified opinion a work of the period of the artist and showing his influence.",
        "sothebys": "In our opinion, a work by an as yet unidentified but distinct hand closely associated with the named artist but not necessarily his pupil."
      }
    },
    {
      "code": "follower-of",
      "warranty_bearing": false,
      "display_pattern": "\"Follower of …\"",
      "meanings": {
        "christies": "In Christie's qualified opinion a work executed in the artist's style but not necessarily by a pupil."
      }
    },
    {
      "code": "manner-of",
      "warranty_bearing": false,
      "display_pattern": "\"Manner of …\"",
      "meanings": {
        "christies": "In Christie's qualified opinion a work executed in the artist's style but of a later date.",
        "sothebys": "In our opinion, a work in the style of the artist and of a later date."
      }
    },
    {
      "code": "after",
      "warranty_bearing": false,
