GET /api/trade/provenance.body:
{
  "schema": "artbitrage.provenance-chain/1",
  "grammar": "aam-provenance/1",
  "purpose": "Round-trip between provenance display paragraphs and structured event chains. POST {display_string} to parse, or {events} to generate the display string. Nothing is stored.",
  "rules": [
    {
      "rule": "A semicolon closing an ownership period means the work passed DIRECTLY to the next party.",
      "status": "verified",
      "source": "https://www.museumprovenance.org/reference/standard/"
    },
    {
      "rule": "A period closing an ownership period means a direct transfer is NOT known to have occurred. When uncertain, the convention assumes not-direct.",
      "status": "verified",
      "source": "https://www.museumprovenance.org/reference/standard/"
    },
    {
      "rule": "Parentheses around an ownership period mark a dealer, auction house, or agent rather than a private owner.",
      "status": "verified-with-variance",
      "source": "AAM/CMOA/Getty CDWA convention. VARIANCE: NCMA and LACMA use square brackets for dealers instead — bracket-vs-parenthesis meaning is institution-specific; only the semicolon/period semantics are universal across surveyed institutions."
    },
    {
      "rule": "Square brackets carry life dates [1880-1955] (open-ended and ? forms allowed), numeric footnote markers [1] (max one per period), and letter citation markers [a].",
      "status": "verified",
      "source": "https://www.museumprovenance.org/reference/standard/"
    },
    {
      "rule": "A question mark marks element-level uncertainty (name?, location?, date?); \"Possibly\"/\"Probably\" opening a period marks whole-period uncertainty.",
      "status": "verified",
      "source": "https://www.museumprovenance.org/reference/standard/"
    },
    {
      "rule": "Acquisition-method phrases precede the acquiring party: purchased by, by descent to, by inheritance to, gift to, bequest to, transferred to, sold to, commissioned by.",
      "status": "verified",
      "source": "https://www.museumprovenance.org/reference/acquisition_methods/"
    },
    {
      "rule": "\"X for Y\" after a purchase = X is the agent, Y the acquirer; \"from Z\" introduces the seller or seller's agent; named sales appear in quotation marks.",
      "status": "verified",
      "source": "https://www.museumprovenance.org/reference/standard/"
    }
  ],
  "parser_honesty": "The parser targets the AAM/CMOA convention above, best-effort. Text it does not recognize is preserved inside party.display or location rather than dropped — absorbed, not warned about — so confidence levels are heuristic and a \"high\" event can still carry unrecognized text in those fields. parse_warnings fire on structural anomalies (empty clauses, marker misuse), and the original display_string is always preserved and hash-covered. Regeneration from events is canonical-form, so round_trip_exact may be false for valid inputs.",
  "privacy": "Parsed party names are echoed back to the caller only — never stored, never resolved to identities. For living private parties prefer the Getty convention: \"Private collection, <region>\".",
  "non_capabilities": {
    "replay_detection": false,
    "uniqueness_not_asserted": true,
    "authenticated": false,
    "identity_verified": false,
    "persisted": false,
    "persistence": {
      "status": "not-persisted-by-application",
      "retrievable_url": null,
      "note": "No application record is created. The caller must carry this unsigned receipt. This does not promise that infrastructure providers keep no ordinary access or security logs."
    },
    "authoritative_effect": "none",
    "issuer_attestation": {
      "signed": false,
      "independently_verifiable": false,
      "note": "witnessed_at is an unattested server observation, not durable proof that Artbitrage issued this receipt."
    },
    "portability": {
      "signed": false,
      "recomputable": true,
      "note": "Recompute content_hash from the normalized record using answering-rhyme.canonical-json/1. The stateless endpoint cannot detect replay or assert uniqueness."
    }
  },
  "disclosure": {
    "informational_only": true,
    "legal_advice": false,
    "note": "Reference arithmetic over cited public schedules. Confirm against the primary source before invoicing. Never legal, tax, or valuation advice."
  }
}

