GET /api/wine/process.body:
{
  "essence": "Zero to one, from earth to glass. Every stage is a smaller gap the winemaker chooses how to bridge.",
  "stages": [
    {
      "id": "terroir",
      "stage": "01",
      "title": "The Ground Decides",
      "what": "Soil, slope, sunlight and climate combine into a single place with a single character; limestone, gravel, schist or clay each leave a signature.",
      "why": "Before a grape grows, the site has already written half the wine. Great wine begins as geography."
    },
    {
      "id": "viticulture",
      "stage": "02",
      "title": "The Vine's Year",
      "what": "Growers prune in winter, train the canopy through spring, and manage the crop through summer so each vine ripens only what it can carry.",
      "why": "A vine left to itself makes many poor grapes; disciplined, it makes few great ones. Quality is a choice made in the field."
    },
    {
      "id": "ripening",
      "stage": "03",
      "title": "Ripening (Véraison)",
      "what": "In late summer the grapes soften and change colour, sugar climbs, acidity falls, and tannins and aromas mature.",
      "why": "This is sunlight becoming sugar — the raw material of every drop of alcohol to come. The whole wine waits on this exchange."
    },
    {
      "id": "harvest",
      "stage": "04",
      "title": "The Decision to Pick",
      "what": "Growers taste and test daily, then pick — by hand or machine — at the balance point between sugar, which becomes alcohol, and acidity, which keeps the wine fresh.",
      "why": "A day early or late changes everything. Harvest is the single most irreversible choice of the year."
    },
    {
      "id": "crush",
      "stage": "05",
      "title": "Breaking the Skin",
      "what": "Grapes are gently crushed and usually parted from their stems, releasing the juice — the must — while reds keep their skins for colour and tannin.",
      "why": "The barrier between sugar and yeast comes down. Fermentation can now begin."
    },
    {
      "id": "fermentation",
      "stage": "06",
      "title": "Sugar Into Spirit",
      "what": "Yeast consumes the grape sugars and produces alcohol and carbon dioxide, with heat and aroma as by-products, over days to weeks.",
      "why": "This is the bridge itself — the moment grape juice becomes wine. Everything before is preparation; everything after is refinement."
    },
    {
      "id": "pressing",
      "stage": "07",
      "title": "Parting Wine From Skin",
      "what": "The new wine is drawn off and the remaining skins are pressed to recover the last, more tannic and concentrated juice.",
      "why": "The winemaker decides how much of the press wine to keep — structure weighed against smoothness."
    },
    {
      "id": "maturation",
      "stage": "08",
      "title": "The Long Wait",
      "what": "Wine rests in stainless steel, oak or concrete for months or years, clarifying, softening and — in oak — gaining spice and a slow trickle of oxygen.",
      "why": "Time rounds what was sharp. Here sunlight and time finish their trade."
    },
    {
      "id": "blending",
      "stage": "09",
      "title": "The Winemaker's Signature",
      "what": "Separate lots — different grapes, plots or barrels — are tasted and married into the final wine, or bottled alone.",
      "why": "The blend is where craft becomes art. A great blend is more than the sum of its parts."
    },
    {
      "id": "bottling",
      "stage": "10",
      "title": "Sealed for Time",
      "what": "The wine is stabilised, sometimes filtered, and sealed under cork or screwcap to continue its slow evolution in glass.",
      "why": "The bottle is a time capsule. What was made in one autumn can be opened decades later."
    }
  ]
}

GET /api/wine/selection.body:
{
  "essence": "Choosing wine is arbitrage too — the gap between the label and the pleasure, bridged by a little knowledge.",
  "guide": [
    {
      "factor": "Vintage",
      "how": "The year on the label is a weather report. In marginal climates a great vintage can outshine a lesser one from the same estate; in warm, steady regions the year matters less."
    },
    {
      "factor": "Region",
      "how": "Region tells you the grape, the style and the rules behind them. Learn a handful of classic pairings — Burgundy for Pinot Noir, Mosel for Riesling, Barolo for Nebbiolo — and you can read a shelf at a glance."
    },
    {
      "factor": "Producer",
      "how": "A careful grower in a modest appellation beats a careless one in a famous one. Names you trust are the surest shortcut to a good bottle."
    },
    {
      "factor": "Reading the label",
      "how": "Look past the front. Alcohol hints at body and ripeness, the appellation signals origin and rules, and words like 'estate' or 'single vineyard' point to tighter control."
    },
    {
      "factor": "Price and value",
      "how": "Price rises faster than quality near the top. The sweet spot is usually just above a region's entry level, or in a great region's less-famous neighbour."
    },
    {
      "factor": "The occasion",
      "how": "Match the wine to the moment and the food, not the price tag. Acidity and bubbles cut through rich dishes; a quiet Tuesday rarely needs a First Growth."
    },
    {
      "factor": "Storage and cellaring",
      "how": "Most wine is made to drink now; only a fraction improves with age. Keep bottles cool, dark and on their side, and open age-worthy wines on their upward curve, not past it."
    }
  ]
}

GET /api/wine/techniques.body:
{
  "techniques": [
    {
      "id": "whole-cluster",
      "name": "Whole-Cluster Fermentation",
      "what": "Fermenting with the grape stems left in rather than destemming.",
      "effect": "Adds structure, a savoury lift and gentle tannin, and can bring a fresh, spicy perfume — used with care in Pinot Noir and Syrah."
    },
    {
      "id": "carbonic-maceration",
      "name": "Carbonic Maceration",
      "what": "Whole, uncrushed grapes ferment from the inside in a carbon-dioxide-filled tank before their skins break.",
      "effect": "Produces vivid colour, low tannin and bright, juicy fruit — the signature of young Beaujolais."
    },
    {
      "id": "sur-lie",
      "name": "Sur Lie Aging",
      "what": "Leaving the wine to rest on its spent yeast cells, the lees, after fermentation.",
      "effect": "Builds texture, a creamy weight and savoury, bready complexity — classic for Muscadet and fine Champagne."
    },
    {
      "id": "batonnage",
      "name": "Bâtonnage",
      "what": "Stirring the settled lees back up through the wine during aging.",
      "effect": "Deepens body and adds a rounder, nuttier richness, often seen in barrel-aged Chardonnay."
    },
    {
      "id": "oak-regime",
      "name": "Oak Regimes",
      "what": "Choosing new versus used barrels, French versus American oak, and the level of toast.",
      "effect": "Dials spice, vanilla, smoke and tannin up or down, and controls how much slow oxygen shapes the wine."
    },
    {
      "id": "late-harvest",
      "name": "Late Harvest",
      "what": "Leaving grapes on the vine well past normal ripeness to concentrate their sugars.",
      "effect": "Makes richer, often sweet wines with intense fruit — the natural sugar can outrun the yeast, leaving sweetness behind."
    },
    {
      "id": "botrytis",
      "name": "Noble Rot (Botrytis)",
      "what": "Encouraging the benevolent fungus Botrytis cinerea to shrivel ripe grapes on the vine.",
      "effect": "Concentrates sugar and acid and adds honeyed, saffron-like complexity — the secret of Sauternes and Tokaji."
    },
    {
      "id": "solera",
      "name": "Solera System",
      "what": "Fractionally blending across stacked barrels so a little old wine seasons each new batch.",
      "effect": "Creates a consistent house style and deep, oxidative character — the heart of Sherry and traditional Madeira."
    },
    {
      "id": "methode-traditionnelle",
      "name": "Méthode Traditionnelle",
      "what": "Provoking a second fermentation inside the sealed bottle to trap the carbon dioxide.",
      "effect": "Gives fine, persistent bubbles and, with lees aging, the toasty depth of true Champagne."
    },
    {
      "id": "cold-soak",
      "name": "Cold Maceration",
      "what": "Chilling crushed red grapes on their skins before fermentation begins.",
      "effect": "Draws out colour and aroma gently, in water rather than alcohol, for a more perfumed, deeply coloured red."
    }
  ],
  "count": 10
}

