{
  "techniques": [
    {
      "id": "entubado",
      "name": "Entubado bunching",
      "what": "Each filler leaf is rolled into its own slender tube before the tubes are gathered into the bunch — the slowest, most exacting way to build a cigar's interior.",
      "effect": "Open, even airflow through every leaf: the best draw a cigar can have, and the fullest expression of the blend."
    },
    {
      "id": "book-bunching",
      "name": "Book and accordion bunching",
      "what": "Filler leaves are laid flat and folded like the pages of a book, or with edges pleated inward accordion-style, then rolled into the binder.",
      "effect": "Faster than entubado and reliable in skilled hands; the accordion fold preserves air channels that plain folding can crush."
    },
    {
      "id": "triple-cap",
      "name": "The triple cap",
      "what": "The head of the cigar is finished with three overlapping turns of cap leaf — the classic Cuban signature, visible as three fine seams.",
      "effect": "The head survives cutting cleanly, and the wrapper stays anchored to the last inch."
    },
