GET /api/pair/principles.body:
{
  "principles": [
    {
      "id": "body-matches-body",
      "principle": "Body matches body",
      "why": "The oldest rule in the pairing canon: neither partner may drown the other. A delicate Connecticut-shade cigar disappears under Amarone, and a featherweight white vanishes in ligero smoke. Generations of tasters agree — weigh both hands before you join them."
    },
    {
      "id": "sweetness-bridges-strength",
      "principle": "Sweetness bridges strength",
      "why": "Fortified wine loves maduro. Tradition holds that residual sugar cushions a dark cigar's power the way a low note supports a loud one — which is why Port and Sherry have sat beside the humidor for two centuries."
    },
    {
      "id": "smoke-wants-sugar-and-acid",
      "principle": "Smoke wants sugar and acid",
      "why": "Tasters have long observed that smoke flattens a dry, neutral wine but flatters a sweet or bright one. Sugar rounds the char; acidity rinses it. The wines that survive a cigar are the ones with something left to give."
    },
    {
      "id": "tannin-meets-tannin",
      "principle": "Tannin meets tannin",
      "why": "Both crafts share the same structure: grape skins and oak give wine its grip, and cured leaf carries a cousin of that grip in every draw. The consensus is that matched structure reads as harmony, while a one-sided grip reads as bitterness."
    },
    {
      "id": "match-the-finish",
      "principle": "Match the finish lengths",
      "why": "A great cigar's flavor lingers for minutes; a short-finish wine leaves the conversation early. Tradition favors long against long — wines built to echo, cigars built to hold the room."
    },
    {
      "id": "terroir-kinship",
      "principle": "Terroir kinship",
      "why": "Vine and leaf both remember their ground. Tasters often find that earthy wines sit naturally beside earthy leaf, volcanic spice beside volcanic spice — not chemistry, but a kinship the palate keeps rediscovering."
    },
    {
      "id": "occasion-rules",
      "principle": "The occasion rules the pair",
      "why": "The hour, the company, and the time you actually have outrank any rulebook. A Churchill demands an unhurried evening; a petit corona and a glass of Champagne can bless a busy one. The right pairing is the one the moment can hold."
    }
  ],
  "count": 7
}

