{
  "schema": "artbitrage.pigments/1",
  "pigment": {
    "id": "prussian-blue",
    "names": [
      "Prussian blue",
      "Berlin blue",
      "Berliner Blau",
      "Paris blue",
      "Milori blue",
      "iron blue",
      "ferric ferrocyanide",
      "Turnbull's blue"
    ],
    "colour_index": "PB27",
    "family": "blue",
    "type": "synthetic-inorganic",
    "origin": {
      "source": "Synthetic; precipitated in a dyer's/alchemist's workshop, not mined. Born from Johann Jacob Diesbach's potash accidentally contaminated with animal matter (Dippel's animal oil) supplying the iron-cyanide component.",
      "geography": "Berlin, Kingdom of Prussia"
    },
    "production": "Historically precipitated by combining an iron(II) salt (green vitriol, FeSO4) with 'yellow prussiate of potash' (potassium ferrocyanide, itself made by calcining potash with dried blood, horn or other nitrogenous animal matter), then oxidising the pale white precipitate in air to the deep blue. The Turnbull's-blue route (iron(II) + ferricyanide) yields the same compound. 'Soluble' (colloidal, K-bearing) and 'insoluble' grades arise from washing and potassium content; Milori blue is a calcined high-tint variant. Modern manufacture reacts sodium/potassium ferrocyanide with an iron(III) salt (e.g. FeCl3), followed by oxidation and milling.",
    "chemistry": {
      "composition": "Iron(III) hexacyanoferrate(II) — a mixed-valence compound containing both Fe2+ and Fe3+ bridged by cyanide ([Fe(CN)6]4-). Usually hydrated and containing interstitial K+ or Na+.",
      "formula": "Fe4[Fe(CN)6]3·xH2O (CI 77510)"
    },
    "dates": {
      "first_attested": {
        "year": 1704,
        "text": "Discovered accidentally in Berlin c. 1704 by dye-maker Johann Jacob Diesbach while trying to make a red cochineal/carmine lake; his potash was contaminated with 'Dippel's animal oil' (distilled from blood and bone), supplying iron-cyanide and yielding blue instead. Sources give the discovery year variously as 1704, 1706 or as late as 1708, so the exact year is genuinely debated — but the ~1704 floor is secure. The earliest firmly dated painting containing it is Pieter van der Werff's 'Entombment of Christ', 1709.",
        "source_url": "https://www.colourlex.com/project/prussian-blue/",
        "truth_status": "contested"
      },
      "synthetic_from": {
        "year": 1704,
        "text": "The first modern synthetic pigment; it has no natural mineral equivalent, so c. 1704 in Berlin is an absolute manufacturing floor for the material. The recipe was kept a trade secret and sold at a premium until John Woodward published it in 1724 (Philosophical Transactions of the Royal Society), after which manufacture spread rapidly across Europe (widely used by ~1750).",
        "source_url": "https://www.ndt.net/article/art2008/papers/029bartoll.pdf",
        "truth_status": "verified"
      },
      "obsolescence": null
    },
    "lightfastness": "Generally good in full mass tone (rated toward ASTM I at full strength), but variable: prone to a partial, reversible photo-fading in thin/pale tints — it can lose colour in strong light and regenerate somewhat in the dark. Irreversible loss occurs in alkaline conditions. Not for fresco or lime.",
    "toxicity": "Practically non-toxic as a pigment: the cyanide is locked in the ferrocyanide complex and is not bioavailable. Insoluble Prussian blue is used medically as an oral antidote (Radiogardase) for thallium and radiocaesium poisoning. It releases hydrogen cyanide only if treated with strong acid or heated to high temperature.",
    "storage": "Keep away from alkaline environments — dilute alkalis decompose it to brown iron(III) hydroxide, so avoid lime, alkaline grounds and fresco; it should not be mixed with lead white or calcium carbonate. Resistant to dilute mineral acids and stable up to ~140 C. Because tints fade reversibly under strong light and recover in the dark, display lighting and dark storage both affect apparent colour. Well characterised by Raman/FTIR (Fe-CN band ~2090 cm-1) and XRF (Fe).",
    "stories": [
      {
        "text": "The accidental birth: Diesbach set out to make a red lake but his contaminated potash (via Dippel's foul blood-and-bone 'animal oil') turned the batch blue — the first synthetic modern pigment, made by mistake.",
        "source_url": "https://www.colourlex.com/project/prussian-blue/",
        "truth_status": "source-declared"
      },
      {
        "text": "The secret held for ~20 years: the manufacturing method was guarded and sold at premium prices until John Woodward published the recipe in the Royal Society's Philosophical Transactions in 1724, breaking the monopoly and letting the pigment spread across Europe.",
        "source_url": "https://www.ndt.net/article/art2008/papers/029bartoll.pdf",
        "truth_status": "verified"
      },
      {
        "text": "As 'bero-ai' (Berlin blue) it transformed Japanese ukiyo-e in the 1830s — the deep blues of Hokusai's 'Great Wave off Kanagawa' and 'Thirty-six Views of Mount Fuji' are Prussian blue, imported into Japan.",
        "source_url": "https://en.wikipedia.org/wiki/Prussian_blue",
        "truth_status": "verified"
      },
      {
        "text": "It later found a second life in medicine: insoluble Prussian blue ('Radiogardase') is a WHO essential-medicines antidote that binds thallium and radioactive caesium in the gut for excretion.",
        "source_url": "https://en.wikipedia.org/wiki/Prussian_blue",
        "truth_status": "verified"
      }
    ],
    "anachronism_marker": {
      "is_marker": true,
      "note": "Strong, reliable dating floor. Prussian blue cannot predate its c. 1704 invention and appears in paintings only from 1709; a European work purporting to be older but containing PB27 is anachronistic or later-restored. It is easy to identify unambiguously (Raman Fe-CN band, XRF iron with no other blue chromophore), making it one of the most trusted anchor pigments in authentication."
    },
    "sources": [
      "https://www.colourlex.com/project/prussian-blue/",
      "https://www.ndt.net/article/art2008/papers/029bartoll.pdf",
      "https://en.wikipedia.org/wiki/Prussian_blue",
      "https://en.wikipedia.org/wiki/Johann_Jacob_Diesbach"
    ],
    "swatch": {
      "hex": "#013A63",
      "approximate": true
    },
    "hazard": {
      "level": "low",
      "tags": [
        "cyanide"
      ],
      "basis": "Practically non-toxic as a pigment: the cyanide is locked in the ferrocyanide complex and is not bioavailable."
    }
  },
  "swatch_note": "Every swatch hex is an honest sRGB approximation only. Real pigment appearance depends on grade, grind, binder, layering and age; effects like Egyptian blue's near-infrared luminescence cannot be shown on a screen at all.",
  "disclosure": {
    "informational_only": true,
    "authentication_advice": false,
    "not_authentication": "A pigment that postdates the claimed date is strong evidence AGAINST authenticity; a period-consistent palette can NEVER prove authenticity. Real pigment identification needs lab analysis (XRF/Raman/cross-section); this endpoint only reasons over pigments you supply, using first-attested dates that themselves carry uncertainty.",
    "note": "Reference facts over cited pigment histories. Every dated milestone and story carries source_url plus a truth_status (verified | source-declared | contested | unverified); descriptive fields are syntheses from each pigment’s cited sources list. Confirm against the primary source and real analysis before drawing a conclusion."
  }
